const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const wilmingtonNC = ee.Geometry.Point([-77.9448, 34.2257]);
    const startDate = '2018-01-01';
    const endDate = '2018-12-31';

    // 2. Data Acquisition & Check
    // Using CHIRPS Daily for precipitation data.
    let precipitationCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
        .filterDate(startDate, endDate)
        .filterBounds(wilmingtonNC);

    const collectionSize = precipitationCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log("Evidence: No CHIRPS images found for the specified date and location.");
        console.log("A: No");
        return;
    }
    console.log(`Evidence: Found ${collectionSize} daily precipitation images for 2018.`);

    // 3. Processing & Calculation
    // Sum all daily images to get a total annual precipitation image.
    const totalPrecipitation = precipitationCollection.select('precipitation').sum();

    // Extract the total precipitation value at the location.
    const precipitationStats = totalPrecipitation.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: wilmingtonNC,
        scale: 5000, // CHIRPS native resolution is ~5.5km
        maxPixels: 1e9
    });

    const totalPrecipitationMM = precipitationStats.get('precipitation').getInfo();

    // 4. Validation & Final Answer
    if (totalPrecipitationMM === null || totalPrecipitationMM === undefined) {
        console.log("Evidence: Calculation failed. Could not retrieve precipitation value.");
        console.log("C3");
        return;
    }

    // Convert millimeters to inches (1 mm = 0.0393701 inches)
    const totalPrecipitationInches = totalPrecipitationMM * 0.0393701;

    console.log(`Evidence: Total calculated rainfall (mm): ${totalPrecipitationMM.toFixed(2)}`);
    console.log(`Evidence: Total calculated rainfall (inches): ${totalPrecipitationInches.toFixed(2)}`);

    const thresholdInches = 90;
    if (totalPrecipitationInches >= thresholdInches) {
        console.log(`Evidence: Rainfall of ${totalPrecipitationInches.toFixed(2)} inches is >= ${thresholdInches} inches.`);
        console.log("A");
    } else {
        console.log(`Evidence: Rainfall of ${totalPrecipitationInches.toFixed(2)} inches is < ${thresholdInches} inches.`);
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during initialization or analysis.');
        console.error(e);
        console.log("D");
    }
}

initEE();
